package com.vignesh.banking.controller;
import com.vignesh.banking.dto.TransferRequest;import com.vignesh.banking.model.*;import com.vignesh.banking.service.BankingService;import org.springframework.data.domain.Page;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/accounts") public class AccountController{ private final BankingService s; public AccountController(BankingService s){this.s=s;} @GetMapping("/me") public List<Account> mine(Authentication a){return s.myAccounts(a.getName());} @PostMapping("/transfer") public String transfer(Authentication a,@RequestBody TransferRequest r){return s.transfer(a.getName(),r);} @GetMapping("/{id}/transactions") public Page<Transaction> history(@PathVariable Long id,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="10") int size){return s.history(id,page,size);} }
